import{_ as i,o as a,c as l,a3 as t,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/lehrkraefte/lehrkraefte-uebersicht.png",d="/bilder/lehrkraefte/menueband.png",b=JSON.parse('{"title":"Das Menüband der Lehrkräfte verwenden","description":"","frontmatter":{"title":"Das Menüband der Lehrkräfte verwenden","source_pageid":271,"source_revision":5236},"headers":[],"relativePath":"schild3/lehrkraefte/menueband-lehrkraefte.md","filePath":"schild3/lehrkraefte/menueband-lehrkraefte.md"}'),h={name:"schild3/lehrkraefte/menueband-lehrkraefte.md"};function o(u,r,c,g,f,k){return a(),l("div",null,[...r[0]||(r[0]=[t('<h1 id="das-menuband-der-lehrkrafte-verwenden" tabindex="-1">Das Menüband der Lehrkräfte verwenden <a class="header-anchor" href="#das-menuband-der-lehrkrafte-verwenden" aria-label="Permalink to &quot;Das Menüband der Lehrkräfte verwenden&quot;">​</a></h1><p><a href="/bilder/lehrkraefte/lehrkraefte-uebersicht.png"><img src="'+s+'" alt="Lehrkräfteliste mit Suchfeld und Sortierung" loading="lazy"></a></p><p><em>Lehrkräfteliste mit Suchfeld und Sortierung — Oberfläche von SchILD-NRW 3.6.0.</em></p><p>Legen Sie Lehrkräfte an, bearbeiten Sie Daten und rufen Sie gemeinsame Aktionen auf. Die Suche und Sortierung stehen bei der Lehrkräfteliste; im Menüband finden Sie unter anderem Export und Berechnung der Unterrichtsverteilung.</p><p>Im Menüband der Lehrkräfte beinhaltet der Bereich <strong>Bearbeitung</strong> die Funktion, Einträge neu anzulegen, zu löschen oder zu verändern.</p><ul><li><strong>Einfügen</strong> erzeugt einen neuen Eintrag für eine neue Lehrkraft.</li><li><strong>Bearbeiten</strong> über Bearbeiten wird ein existierender Eintrag verändert. <ul><li><em>Übernehmen</em> speichert die aktuelle Änderung. Ebenso wird eine Änderung übernommen, wenn das aktuell bearbeitete Feld verlassen wird.</li><li><em>Abbrechen</em> beendet die aktuelle Änderung.</li></ul></li><li><strong>Aktualisieren</strong> liest die Liste der Lehrkräfte erneut ein.</li></ul><p>Sollen bestehende Einträge gelöscht werden, erscheinen mehrere Warnhinweise, die noch bestätigt werden müssen.</p>',7),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,"Warnhinweise sollten genau gelesen werden, denn Änderungen können nicht rückgängig gemacht werden.")],-1),t("<p>Unter <strong>Aktionen</strong> finden Sie den Export sowie Berechnungen anhand der zeitabhängigen Daten und der Unterrichtseinsätze.</p><ul><li><strong>UVD berechnen</strong> berechnet die Unterrichtsverteilung (UVD) anhand der zeitabhängigen Lehrkräftedaten. Dabei werden unter anderem die zugeordneten Fächer und Kurse ausgewertet.</li><li>Über <strong>Export</strong> können Lehrkräftedaten ausgegeben werden. Bei einem Klick auf den Schalter öffnet sich Tabelle mit den wichtigsten Daten der Lehrerinnen und Lehrer. Anschließend ist es möglich, diese Tabelle als Excel-Datei zu speichern.</li></ul><p>Über die <strong>Filteroptionen</strong> lassen sich nur die auf <em>sichtbar</em> gestellten Lehrkräfte oder <em>alle&#39; anzeigen.</em></p><p>Wurde eine Statistikprüfung ausgeführt, können nun auch die Lehrkräfte, bei denen ein <em>Statistikfehler</em> vorliegt anzeigt werden. Somit werden nur Datensätze angezeigt, die bei der Gesamtprüfung für die Statistik fehlerhaft waren.</p><p>Das Suchfeld befindet sich oberhalb der Lehrkräfteliste. Darüber wählen Sie <strong>Nachname</strong>, <strong>Internes Kürzel</strong> oder <strong>Sortiernummer</strong> für die Sortierung.</p><p>Die angezeigten Spalten lassen sich über das Kontextmenü der Lehrkräftetabelle anpassen. Zusätzliche Informationsspalten können dort ein- und ausgeblendet werden.</p>",6),e("details",{"data-hint-kind":"details",class:"details custom-block"},[e("summary",null,[e("svg",{class:"hint-icon","data-icon":"details","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m9 5 7 7-7 7"})]),n("Früheres Verfahren: Lehrkräftemenü vor SchILD-NRW 3.6.0")]),e("p",null,[e("a",{href:"/bilder/lehrkraefte/menueband.png"},[e("img",{src:d,alt:"Das Menüband im Bereich Lehrkräfte.",loading:"lazy"})])]),e("p",null,[e("em",null,"Das Menüband im Bereich Lehrkräfte.")])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Men%C3%BCband_(Lehrkr%C3%A4fte)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 5236.")],-1)])])}const p=i(h,[["render",o]]);export{b as __pageData,p as default};
